package com.saxonica.ee.bytecode.util;

import net.sf.saxon.om.Item;
import net.sf.saxon.om.SequenceIterator;

/**
 * Information about a SequenceIterator in generated bytecode: defines
 * the class of iterator, and the class of items that it returns.
 */

public class IteratorDetails {

    public final Class<? extends SequenceIterator> iteratorClass;
    public final Class<? extends Item> itemClass;

    public IteratorDetails(Class<? extends SequenceIterator> iteratorClass, Class<? extends Item> itemClass) {
        this.iteratorClass = iteratorClass;
        this.itemClass = itemClass;
    }

}

